"""Regression tests for the shared certified-consensus authentication core.

``locate_cert``/``locate_cert_evidence`` (count quorum) and
``locate_weighted_cert_evidence`` (weight threshold) share one
certificate-verification, observation-verification and query-binding
implementation. The golden evidence bytes below were produced by the
public entry points before that sharing was introduced; reproducing them
byte for byte — and auditing them successfully — pins the public
behaviour of both tally paths.
"""

import json
import unittest

from nearproof import (
    BoundAttestedObservation,
    CertifiedConsensusEvidence,
    ConsensusPolicy,
    RangeDecision,
    VerifierTrust,
    attest_observation_for_point,
    audit_cert_evidence,
    audit_weighted_cert_evidence,
    cert,
    locate_cert,
    locate_cert_evidence,
    locate_weighted_cert_evidence,
)

ROOT = b"\x09" * 32
OTHER_ROOT = b"\x08" * 32
KEYS = {"a": b"\xaa" * 32, "b": b"\xbb" * 32, "c": b"\xcc" * 32, "d": b"\xdd" * 32}
POSITIONS = {"a": (3.0, 0.0), "b": (0.0, 4.0), "c": (0.0, 0.0), "d": (50.0, 50.0)}
POINT = (0.0, 0.0)
CONTEXT = "room-7"

# Frozen output of the pre-refactor public entry points for the fixtures
# below (three verifiers a/b/c, an extra unused certificate d, weights
# a=5/b=1/c=1 with threshold 5, and a single-verifier weighted run).
GOLDEN_PLAIN = b'{"version":1,"body":"","mac":"f9b730016bb4b8e42385dafca66b5e067838f014f24335cc679a5356b9367865"}'
GOLDEN_WEIGHTED = b'{"version":1,"body":"","mac":"8214d1aa2f74687e42360bfcef9b1d7b2af3c2c7110c1948499ae164e926b803"}'
GOLDEN_WEIGHTED_SINGLE = b'{"version":1,"body":"","mac":"5285b969e90aecb7a0ac82d44b1c3fbcd861338e9b92bedd331f688dd68bb0b7"}'


def trust(ident, *, root=ROOT):
    x, y = POSITIONS[ident]
    return cert(ident, x, y, KEYS[ident], root)


def record(ident, upper_bound=5.0, *, point=POINT, context=CONTEXT, accepted=True):
    x, y = POSITIONS[ident]
    return attest_observation_for_point(
        ident,
        x,
        y,
        RangeDecision(sample_count=1, upper_bound=upper_bound, accepted=accepted),
        point,
        context,
        0.0,
        KEYS[ident],
    )


def triangle_records(**kwargs):
    return [record("a", **kwargs), record("b", **kwargs), record("c", **kwargs)]


def triangle_trusts():
    # The extra "d" certificate is valid but unused by the records.
    return [trust("a"), trust("b"), trust("c"), trust("d")]


def triangle_policy():
    return ConsensusPolicy({"a": 5, "b": 1, "c": 1}, 5)


def canonical(payload):
    return json.dumps(payload, separators=(",", ":"), allow_nan=False).encode("utf-8")


def retamper(evidence_bytes, mutate):
    """Decode golden evidence, mutate the body, re-sign the outer layer.

    The outer MAC is recomputed with the correct root, so a rejection can
    only come from the inner authentication or consensus re-computation.
    """
    outer = json.loads(evidence_bytes)
    body = json.loads(bytes.fromhex(outer["body"]))
    mutate(body)
    import hashlib
    import hmac

    prefix = b"NPCCE1" if len(body) == 5 else b"NPWCE1"
    new_body = canonical(body)
    outer["body"] = new_body.hex()
    outer["mac"] = hmac.new(ROOT, prefix + new_body, hashlib.sha256).hexdigest()
    return canonical(outer)


class GoldenEvidenceCompatibilityTest(unittest.TestCase):
    def test_plain_evidence_bytes_reproduced(self):
        evidence = locate_cert_evidence(
            triangle_records(), POINT, CONTEXT, triangle_trusts(), ROOT
        )
        self.assertEqual(evidence.to_bytes(), GOLDEN_PLAIN)

    def test_weighted_evidence_bytes_reproduced(self):
        evidence = locate_weighted_cert_evidence(
            triangle_records(), triangle_trusts(), POINT, CONTEXT,
            triangle_policy(), ROOT,
        )
        self.assertEqual(evidence.to_bytes(), GOLDEN_WEIGHTED)

    def test_weighted_single_verifier_evidence_bytes_reproduced(self):
        evidence = locate_weighted_cert_evidence(
            [record("c")], [trust("c")], POINT, CONTEXT,
            ConsensusPolicy({"c": 2}, 2), ROOT,
        )
        self.assertEqual(evidence.to_bytes(), GOLDEN_WEIGHTED_SINGLE)

    def test_golden_bytes_deserialize_and_audit(self):
        evidence = CertifiedConsensusEvidence.from_bytes(GOLDEN_PLAIN)
        self.assertEqual(evidence.to_bytes(), GOLDEN_PLAIN)
        consensus = audit_cert_evidence(GOLDEN_PLAIN, ROOT)
        self.assertEqual(consensus.total, 3)
        self.assertEqual(consensus.support, 3)
        self.assertEqual(consensus.rejected, ())
        self.assertTrue(consensus.accepted)

    def test_golden_weighted_bytes_deserialize_and_audit(self):
        consensus = audit_weighted_cert_evidence(GOLDEN_WEIGHTED, ROOT)
        self.assertEqual(consensus.total_weight, 7)
        self.assertEqual(consensus.support_weight, 7)
        self.assertEqual(consensus.rejected, ())
        self.assertTrue(consensus.accepted)
        single = audit_weighted_cert_evidence(GOLDEN_WEIGHTED_SINGLE, ROOT)
        self.assertEqual(single.total_weight, 2)
        self.assertTrue(single.accepted)

    def test_permutation_and_object_bytes_mixing_preserve_bytes(self):
        records = triangle_records()
        trusts = triangle_trusts()
        shuffled_records = [records[2].to_bytes(), records[0], records[1].to_bytes()]
        shuffled_trusts = [trusts[3], trusts[2].to_bytes(), trusts[0], trusts[1].to_bytes()]
        plain = locate_cert_evidence(
            iter(shuffled_records), POINT, CONTEXT, iter(shuffled_trusts), ROOT
        )
        self.assertEqual(plain.to_bytes(), GOLDEN_PLAIN)
        weighted = locate_weighted_cert_evidence(
            iter(shuffled_records), iter(shuffled_trusts), POINT, CONTEXT,
            triangle_policy(), ROOT,
        )
        self.assertEqual(weighted.to_bytes(), GOLDEN_WEIGHTED)

    def test_extra_unused_trust_is_not_frozen_into_evidence(self):
        body = json.loads(bytes.fromhex(json.loads(GOLDEN_PLAIN)["body"]))
        self.assertEqual(len(body[2]), 3)  # records
        self.assertEqual(len(body[3]), 3)  # trusts: the unused "d" is absent
        weighted_body = json.loads(bytes.fromhex(json.loads(GOLDEN_WEIGHTED)["body"]))
        self.assertEqual(len(weighted_body[3]), 3)
        self.assertEqual(list(weighted_body[4]), ["a", "b", "c"])  # weights


class AuthenticationFailureRegressionTest(unittest.TestCase):
    def test_root_contract(self):
        for call in (
            lambda root: locate_cert(triangle_records(), POINT, CONTEXT, triangle_trusts(), root),
            lambda root: locate_cert_evidence(triangle_records(), POINT, CONTEXT, triangle_trusts(), root),
            lambda root: locate_weighted_cert_evidence(
                triangle_records(), triangle_trusts(), POINT, CONTEXT, triangle_policy(), root
            ),
            lambda root: audit_cert_evidence(GOLDEN_PLAIN, root),
            lambda root: audit_weighted_cert_evidence(GOLDEN_WEIGHTED, root),
        ):
            with self.assertRaises(TypeError):
                call("not-bytes")
            with self.assertRaises(ValueError):
                call(b"")
            with self.assertRaises(ValueError):
                call(OTHER_ROOT)

    def test_resigned_outer_cannot_mask_tampered_record_mac(self):
        def mutate(body):
            raw = bytearray(bytes.fromhex(body[2][0]))
            record_obj = json.loads(bytes(raw))
            record_obj["mac"] = "00" * 32
            body[2][0] = canonical(record_obj).hex()

        tampered = retamper(GOLDEN_PLAIN, mutate)
        with self.assertRaises(ValueError):
            audit_cert_evidence(tampered, ROOT)

    def test_resigned_outer_cannot_mask_tampered_consensus(self):
        def mutate(body):
            body[4][3] = False  # consensus accepted flipped

        tampered = retamper(GOLDEN_PLAIN, mutate)
        with self.assertRaises(ValueError):
            audit_cert_evidence(tampered, ROOT)

    def test_resigned_outer_cannot_mask_tampered_weighted_consensus(self):
        def mutate(body):
            body[6][1] = 0  # support_weight zeroed

        tampered = retamper(GOLDEN_WEIGHTED, mutate)
        with self.assertRaises(ValueError):
            audit_weighted_cert_evidence(tampered, ROOT)

    def test_missing_certificate_rejected(self):
        with self.assertRaises(ValueError):
            locate_cert(triangle_records(), POINT, CONTEXT, triangle_trusts()[:2], ROOT)

    def test_duplicate_ids_rejected(self):
        records = triangle_records()
        with self.assertRaises(ValueError):
            locate_cert(records + [records[0]], POINT, CONTEXT, triangle_trusts(), ROOT)
        trusts = triangle_trusts()
        with self.assertRaises(ValueError):
            locate_cert(triangle_records(), POINT, CONTEXT, trusts + [trusts[0]], ROOT)

    def test_binding_mismatch_rejected(self):
        other_point_record = record("a", point=(1.0, 1.0))
        with self.assertRaises(ValueError):
            locate_cert(
                [other_point_record, record("b"), record("c")],
                POINT, CONTEXT, triangle_trusts(), ROOT,
            )
        other_context_record = record("a", context="room-8")
        with self.assertRaises(ValueError):
            locate_cert(
                [other_context_record, record("b"), record("c")],
                POINT, CONTEXT, triangle_trusts(), ROOT,
            )

    def test_weight_set_mismatch_rejected(self):
        with self.assertRaises(ValueError):
            locate_weighted_cert_evidence(
                triangle_records(), triangle_trusts(), POINT, CONTEXT,
                ConsensusPolicy({"a": 1, "b": 1, "z": 1}, 2), ROOT,
            )
        with self.assertRaises(ValueError):
            locate_weighted_cert_evidence(
                triangle_records(), triangle_trusts(), POINT, CONTEXT,
                ConsensusPolicy({"a": 1, "b": 1}, 2), ROOT,
            )


class TallyDifferenceRegressionTest(unittest.TestCase):
    def test_plain_requires_three_observations_weighted_allows_one(self):
        with self.assertRaises(ValueError):
            locate_cert(
                [record("a"), record("b")], POINT, CONTEXT,
                [trust("a"), trust("b")], ROOT,
            )
        evidence = locate_weighted_cert_evidence(
            [record("c")], [trust("c")], POINT, CONTEXT,
            ConsensusPolicy({"c": 2}, 2), ROOT,
        )
        consensus = audit_weighted_cert_evidence(evidence.to_bytes(), ROOT)
        self.assertTrue(consensus.accepted)

    def test_weighted_accepts_where_count_quorum_fails(self):
        # Only "c" covers the point: count quorum 3 fails, but c's weight
        # alone reaches the threshold.
        records = [record("a", 2.0), record("b", 2.0), record("c"), record("d", 2.0)]
        trusts = [trust("a"), trust("b"), trust("c"), trust("d")]
        consensus = locate_cert(records, POINT, CONTEXT, trusts, ROOT)
        self.assertFalse(consensus.accepted)
        self.assertEqual(consensus.rejected, ("a", "b", "d"))
        policy = ConsensusPolicy({"a": 1, "b": 1, "c": 10, "d": 1}, 10)
        evidence = locate_weighted_cert_evidence(
            records, trusts, POINT, CONTEXT, policy, ROOT
        )
        weighted = audit_weighted_cert_evidence(evidence.to_bytes(), ROOT)
        self.assertTrue(weighted.accepted)
        self.assertEqual(weighted.support_weight, 10)
        self.assertEqual(weighted.rejected, ("a", "b", "d"))

    def test_weighted_rejects_where_count_quorum_passes(self):
        # a, b, c cover the point (count quorum met) but their combined
        # weight falls short of the threshold.
        records = [record("a"), record("b"), record("c"), record("d", 2.0)]
        trusts = [trust("a"), trust("b"), trust("c"), trust("d")]
        consensus = locate_cert(records, POINT, CONTEXT, trusts, ROOT)
        self.assertTrue(consensus.accepted)
        policy = ConsensusPolicy({"a": 1, "b": 1, "c": 1, "d": 10}, 11)
        evidence = locate_weighted_cert_evidence(
            records, trusts, POINT, CONTEXT, policy, ROOT
        )
        weighted = audit_weighted_cert_evidence(evidence.to_bytes(), ROOT)
        self.assertFalse(weighted.accepted)
        self.assertEqual(weighted.support_weight, 3)

    def test_geometric_miss_is_a_rejection_not_an_exception(self):
        # "c" sits exactly at the queried point, so use a/b/d: every disk
        # misses and the result is a rejected consensus, not an exception.
        records = [record("a", 2.0), record("b", 2.0), record("d", 2.0)]
        trusts = [trust("a"), trust("b"), trust("d")]
        evidence = locate_cert_evidence(records, POINT, CONTEXT, trusts, ROOT)
        consensus = audit_cert_evidence(evidence.to_bytes(), ROOT)
        self.assertFalse(consensus.accepted)
        self.assertEqual(consensus.support, 0)
        self.assertEqual(consensus.rejected, ("a", "b", "d"))

    def test_decision_accepted_flag_is_ignored(self):
        records = triangle_records(accepted=False)
        consensus = locate_cert(records, POINT, CONTEXT, triangle_trusts(), ROOT)
        self.assertTrue(consensus.accepted)
        self.assertEqual(consensus.rejected, ())


if __name__ == "__main__":
    unittest.main()
